export function translator(language:Language){return (key:string)=>rows[key]?.[languages.indexOf(language)]||key;}
export function label(key:string,t:(key:string)=>string){const trimmed=key.replace(/_([a-z])/g,(_,s)=>s.toUpperCase());const translated=t(trimmed);return translated===trimmed?key.replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' '):translated;}
export function statusLabel(value:string,t:(key:string)=>string){const map:Record<string,string>={DRAFT:'draft',OPEN:'pending',PENDING:'pending',ACTIVE:'active',WORKING:'working',ACCEPT:'accept',REJECT:'rejected',APPROVE:'approve',DISPUTE:'dispute',AWAY_PENDING_REASON:'attention',SERVICE_TASK:'service',WAITING_WORK:'waiting',IN_PROGRESS:'working',ON_BREAK:'break',PRIVATE_BREAK:'break',APPROVED:'approved',ACCEPTED:'approved',COMPLETED:'completed',CLOSED:'completed',ENDED:'completed',DONE:'completed',SUBMITTED:'review',QUALITY_REVIEW:'review',REVIEW:'review',REJECTED:'rejected',RETURNED:'rejected',READY:'plan',PLANNED:'plan',PAID:'completed',AWAITING_DELIVERY:'awaitingDelivery',DEAD_LETTER:'deadLetter',UNKNOWN:'unknown',PENDING_APPROVAL:'pendingApproval',RECONCILED:'reconciled',LOCKED:'locked',QUARANTINED:'quarantined',RETRY_SCHEDULED:'retryScheduled',QUEUED:'queued',DEFERRED:'deferred',SENDING:'sending',RUNNING:'working',FAILED:'failed',BLOCKED:'blockedState',CANCELLED:'cancelled',RECORDED:'recorded',REVERSED:'reversed',PRELIMINARY:'preliminary',ACCOUNTANT_VERIFIED:'accountantVerified',CALCULATED:'calculated',UNCONFIRMED:'unconfirmed',API_ACCEPTED:'providerAccepted',ACCEPTED_BY_PROVIDER:'providerAccepted',SENT:'sent',DELIVERED:'delivered',READ:'read',DISPUTED:'disputed',FULL:'fullyAcknowledged',PARTIAL:'partiallyAcknowledged',MATCHED:'matched',DISCREPANCY_RECORDED:'discrepancyRecorded',TRANSFER_EVIDENCE_CONFIRMED:'transferEvidenceConfirmed',WEB_AVAILABLE:'webAvailable',AI_ACTIVE:'aiConsultation',HANDOFF_PENDING:'humanQueued',HUMAN_QUEUED:'humanQueued',HUMAN_ACTIVE:'humanActive',RESOLVED:'resolved',NO_APPROVED_CALENDAR:'noApprovedCalendar',NOT_APPLICABLE:'notApplicable'};return t(map[value]||value);}
